<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api/client'
type DS={id:string,name:string,type:string,host:string,port:number,username:string,database?:string,schema?:string,jdbc_url?:string,driver_class?:string,cdc_url?:string,tls_mode?:string,tls_server_name?:string,tls_ca_cert?:string;tls_client_cert?:string}
type SchemaObject={schema:string;name:string;type:string;related_to?:string;ddl?:string;definition?:string}
const items=ref<DS[]>([]),dialog=ref(false),testing=ref(''),editing=ref(''),objectsDialog=ref(false),objects=ref<SchemaObject[]>([]),objectsTitle=ref('')
const form=reactive({name:'',type:'mysql',host:'127.0.0.1',port:3306,username:'root',password:'',database:'',schema:'',jdbc_url:'',driver_class:'',cdc_url:'',tls_mode:'DISABLE',tls_server_name:'',tls_ca_cert:'',tls_client_cert:'',tls_client_key:''})
const tlsCapable=computed(()=>['mysql','mariadb','polardbx','tidb','oceanbase_mysql','polardb_mysql','postgresql','polardb_postgresql','opengauss','kingbase','gaussdb','sqlserver','oracle','db2'].includes(form.type))
const providerDSN=computed(()=>['dameng','gbase8s'].includes(form.type))
function defaultTLSMode(t:string){return ['postgresql','polardb_postgresql','opengauss','kingbase','sqlserver','db2'].includes(t)?'PREFERRED':'DISABLE'}
watch(()=>form.type,(v)=>{if(editing.value)return;form.tls_mode=defaultTLSMode(v);form.tls_server_name='';form.tls_ca_cert='';form.tls_client_cert='';form.tls_client_key='';if(v==='postgresql'||v==='polardb_postgresql'||v==='opengauss'||v==='gaussdb'){form.port=5432;form.username='postgres'}else if(v==='oracle'){form.port=1521}else if(v==='sqlserver'){form.port=1433}else if(v==='db2'){form.port=50000}else if(v==='dameng'){form.port=5236}else if(v==='kingbase'){form.port=54321}else if(v==='gbase'){form.port=5258}else if(v==='gbase8s'){form.port=9088}else if(['mysql','mariadb','polardbx','tidb','oceanbase_mysql','polardb_mysql'].includes(v)){form.port=3306;form.username='root'}})
async function load(){items.value=await api('/api/v1/datasources')}
function reset(){editing.value='';Object.assign(form,{name:'',type:'mysql',host:'127.0.0.1',port:3306,username:'root',password:'',database:'',schema:'',jdbc_url:'',driver_class:'',cdc_url:'',tls_mode:'DISABLE',tls_server_name:'',tls_ca_cert:'',tls_client_cert:'',tls_client_key:''})}
function openCreate(){reset();dialog.value=true}
function openEdit(d:DS){editing.value=d.id;Object.assign(form,{name:d.name,type:d.type,host:d.host,port:d.port,username:d.username,password:'',database:d.database||'',schema:d.schema||'',jdbc_url:d.jdbc_url||'',driver_class:d.driver_class||'',cdc_url:d.cdc_url||'',tls_mode:d.tls_mode||defaultTLSMode(d.type),tls_server_name:d.tls_server_name||'',tls_ca_cert:d.tls_ca_cert||'',tls_client_cert:d.tls_client_cert||'',tls_client_key:''});dialog.value=true}
async function save(){try{if(editing.value)await api(`/api/v1/datasources/${editing.value}`,{method:'PUT',body:JSON.stringify(form)});else await api('/api/v1/datasources',{method:'POST',body:JSON.stringify(form)});dialog.value=false;form.password='';await load()}catch(e:any){ElMessage.error(e.message)}}
async function test(id:string){testing.value=id;try{const r=await api<{version:string;protocol?:string;capabilities?:string[];note?:string}>(`/api/v1/datasources/${id}/test`,{method:'POST'});const caps=r.capabilities||[];if(caps.includes('full-read')||caps.includes('full-write'))ElMessage.success(`Native 连接测试成功：${r.version}`);else if(caps.includes('protocol-probe'))ElMessage.success(`Native ${r.protocol||''} 协议握手成功；迁移能力仍在开发：${r.note||''}`);else ElMessage.success('TCP 端点连通；该数据库 Native Connector 尚未实现迁移能力')}catch(e:any){ElMessage.error(e.message)}finally{testing.value=''}}
async function remove(d:DS){try{await ElMessageBox.confirm(`确认删除数据源 ${d.name}？`,'删除数据源',{type:'warning'});await api(`/api/v1/datasources/${d.id}`,{method:'DELETE'});await load()}catch(e:any){if(e!=='cancel')ElMessage.error(e.message||String(e))}}
async function inspectObjects(d:DS){const schema=d.schema||d.database;if(!schema){ElMessage.warning('请先配置默认 Schema/数据库');return}try{objects.value=await api<SchemaObject[]>(`/api/v1/datasources/${d.id}/objects?schema=${encodeURIComponent(schema)}`);objectsTitle.value=`Schema 对象 - ${d.name} / ${schema}`;objectsDialog.value=true}catch(e:any){ElMessage.error(e.message)}}
onMounted(load)
</script>
<template><div><div class="page-title"><div><h1>数据源</h1><p>QMigration Unified Engine 当前原生 Full Load 支持 MySQL、PostgreSQL 及 PostgreSQL Wire 兼容的 openGauss/Kingbase/GaussDB；RC26 为 openGauss mppdb_decoding 与 Kingbase kboutput 增加独立实验性 Source CDC；TiDB 可通过独立 TiCDC + Kafka Endpoint 启用实验性 Native CDC（RC25 支持多 Partition Resolved-TS 合并与 Kafka TLS + SASL PLAIN/SCRAM）；OceanBase MySQL 可通过独立 ODP/Binlog Service Endpoint 启用实验性 Native CDC；Oracle TNS/TTC 与 SQL Server TDS 已具备实验性原生数据面；DB2 LUW 提供实验性 db2ReadLog CDC；GBase 8a 提供实验性 Native Full，GBase 8s 提供 CSDK/ODBC Full/Target Apply + qualification-gated syscdcv1 Source CDC；凭据 AES-256-GCM 加密保存</p></div><el-button type="primary" @click="openCreate">新增数据源</el-button></div><div class="panel"><el-table :data="items"><el-table-column prop="name" label="名称"/><el-table-column prop="type" label="类型"/><el-table-column label="地址"><template #default="s">{{s.row.host}}:{{s.row.port}}</template></el-table-column><el-table-column prop="database" label="数据库"/><el-table-column prop="schema" label="默认 Schema"/><el-table-column prop="username" label="用户"/><el-table-column label="TLS" width="110"><template #default="s"><el-tag :type="s.row.tls_mode==='REQUIRED'?'success':s.row.tls_mode==='PREFERRED'?'warning':'info'">{{s.row.tls_mode||'DISABLE'}}</el-tag></template></el-table-column><el-table-column label="操作" width="290"><template #default="s"><el-button size="small" :loading="testing===s.row.id" @click="test(s.row.id)">测试</el-button><el-button size="small" @click="inspectObjects(s.row)">对象</el-button><el-button size="small" @click="openEdit(s.row)">编辑</el-button><el-button size="small" type="danger" plain @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></div>
<el-dialog v-model="dialog" :title="editing?'编辑数据源':'新增数据源'" width="720"><el-form label-width="90"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="类型"><el-select v-model="form.type" style="width:100%"><el-option label="MySQL" value="mysql"/><el-option label="MariaDB" value="mariadb"/><el-option label="PolarDB-X" value="polardbx"/><el-option label="TiDB" value="tidb"/><el-option label="OceanBase MySQL" value="oceanbase_mysql"/><el-option label="PolarDB MySQL" value="polardb_mysql"/><el-option label="PostgreSQL" value="postgresql"/><el-option label="PolarDB PostgreSQL" value="polardb_postgresql"/><el-option label="Oracle (QMigration Native TNS/TCPS Probe)" value="oracle"/><el-option label="SQL Server (QMigration Native TDS/TLS + CDC Experimental)" value="sqlserver"/><el-option label="DB2 LUW (Native DRDA + db2ReadLog CDC Experimental)" value="db2"/><el-option label="openGauss (Native PG Wire + mppdb_decoding CDC Experimental)" value="opengauss"/><el-option label="Kingbase (Native PG Wire + kboutput CDC Experimental)" value="kingbase"/><el-option label="达梦 DM8 (Native Full + Archived Log CDC Experimental)" value="dameng"/><el-option label="GaussDB (Native PG Wire + Binary CDC Experimental)" value="gaussdb"/><el-option label="GBase 8a MPP (Native Full Experimental)" value="gbase"/><el-option label="GBase 8s V8.8 (CSDK Full/Target + Source CDC Experimental)" value="gbase8s"/></el-select></el-form-item><el-form-item label="Host"><el-input v-model="form.host"/></el-form-item><el-form-item label="Port"><el-input-number v-model="form.port" :min="1" :max="65535"/></el-form-item><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password :placeholder="editing?'留空表示保持原密码':''"/></el-form-item><el-form-item label="数据库"><el-input v-model="form.database" placeholder="DB2 为 RDB/database name；PostgreSQL 为连接数据库；MySQL 系即 Schema/Database"/></el-form-item><el-form-item label="默认 Schema"><el-input v-model="form.schema" :placeholder="form.type==='postgresql'||form.type==='polardb_postgresql'?'默认 public':'留空时使用数据库名'"/></el-form-item><el-form-item v-if="form.type==='tidb'" label="TiCDC URL"><el-input v-model="form.cdc_url" placeholder="ticdc://ticdc-host:8300?brokers=kafka1:9092,kafka2:9092&kafka_partitions=4"/><div style="font-size:12px;color:#909399;margin-top:4px">FULL+CDC 使用 TiCDC OpenAPI + QMigration Native Kafka Consumer；RC25 支持多 Partition Resolved-TS 安全合并、Kafka TLS/mTLS 与 SASL/PLAIN + SCRAM-SHA-256/512。URL 禁止嵌入用户名/密码；SASL 凭据通过 Worker 环境变量注入。</div></el-form-item><el-form-item v-else-if="form.type==='oceanbase_mysql'" label="Binlog URL"><el-input v-model="form.cdc_url" placeholder="obbinlog://odp-host:2883 或 obbinlogs://odp-host:2883?server_name=odp.example"/><div style="font-size:12px;color:#909399;margin-top:4px">FULL+CDC 通过租户 ODP 转发 MySQL Binlog Dump 到 OceanBase Binlog Service；请填写 ODP 订阅入口，不要填写 Binlog Server 2983 管理端口。URL 禁止嵌入用户名/密码。</div></el-form-item><el-form-item v-else-if="form.type==='db2'" label="Log Agent URL"><el-input v-model="form.cdc_url" placeholder="db2log://db2-agent:8787 或 db2logs://db2-agent:8787?server_name=agent.example"/><div style="font-size:12px;color:#909399;margin-top:4px">FULL+CDC 通过源端 QMigration DB2 Log Agent 调用 IBM db2ReadLog；源表需 DATA CAPTURE CHANGES。Bearer Token 请通过 Worker/Agent 环境变量注入，禁止写入 URL。</div></el-form-item><el-form-item v-else-if="form.type==='gbase8s'" label="CDC Agent URL"><el-input v-model="form.cdc_url" placeholder="gbase8scdc://127.0.0.1:9188 或 gbase8scdcs://agent:9188"/><div style="font-size:12px;color:#909399;margin-top:4px">RC28 FULL+CDC 使用源端 qmigration-gbase8s-cdc-agent 调用 syscdcv1/CSDK CDC；要求 Agent API/native C ABI v4 schema-fence + capture-lineage provider（可 SHA-256 pin）。BLOB/CLOB 仅在 Provider 声明 cdc-event-owned-lob-v1 并提供长度/SHA-256 事件镜像证明时启用，Agent Token/CA 通过 Worker 环境变量注入，数据库凭据不会发送给 Agent API。</div></el-form-item><template v-if="tlsCapable"><el-divider content-position="left">Native TLS</el-divider><el-form-item label="TLS 模式"><el-select v-model="form.tls_mode" style="width:100%"><el-option label="DISABLE - 明文" value="DISABLE"/><el-option label="PREFERRED - 服务端支持则启用 TLS" value="PREFERRED"/><el-option label="REQUIRED - 必须 TLS" value="REQUIRED"/></el-select></el-form-item><el-form-item v-if="form.tls_mode!=='DISABLE'" label="Server Name"><el-input v-model="form.tls_server_name" placeholder="证书主机名；留空使用 Host"/></el-form-item><el-form-item v-if="form.tls_mode!=='DISABLE'" label="CA 证书"><el-input v-model="form.tls_ca_cert" type="textarea" :rows="4" placeholder="可选 PEM；留空使用系统 CA。TLS 握手会校验证书和主机名"/></el-form-item><el-form-item v-if="form.tls_mode!=='DISABLE'" label="客户端证书"><el-input v-model="form.tls_client_cert" type="textarea" :rows="4" placeholder="可选 mTLS client certificate PEM"/></el-form-item><el-form-item v-if="form.tls_mode!=='DISABLE'" label="客户端私钥"><el-input v-model="form.tls_client_key" type="textarea" :rows="4" :placeholder="editing?'留空表示保持已有私钥；输入新 PEM 会加密替换':'可选 mTLS client private key PEM（AES-256-GCM 加密保存）'"/></el-form-item></template><template v-if="providerDSN"><el-divider content-position="left">Vendor SQL Provider</el-divider><el-form-item :label="form.type==='gbase8s'?'ODBC DSN':'Provider DSN'"><el-input v-model="form.jdbc_url" :placeholder="form.type==='gbase8s'?'odbc:GBASE8S_APP（禁止包含 UID/PWD）':'可选；留空由 Native Connector 根据 Host/Port/凭据构造'"/><div v-if="form.type==='gbase8s'" style="font-size:12px;color:#909399;margin-top:4px">仅保存非敏感 ODBC DSN/属性；禁止填写 UID/PWD。用户名和密码使用上方数据源凭据，并继续由 QMigration 加密保存。运行节点需安装匹配版本 GBase Client-SDK/unixODBC 并加载 provider plugin。</div></el-form-item><el-form-item label="Driver Name"><el-input v-model="form.driver_class" :placeholder="form.type==='gbase8s'?'odbc':'dm'"/></el-form-item></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="objectsDialog" :title="objectsTitle" width="1000"><el-table :data="objects" max-height="520"><el-table-column prop="type" label="类型" width="120"/><el-table-column prop="name" label="名称" width="200"/><el-table-column prop="related_to" label="关联表" width="180"/><el-table-column prop="ddl" label="DDL/定义" min-width="420"><template #default="s"><el-input :model-value="s.row.ddl||s.row.definition||''" type="textarea" :rows="3" readonly/></template></el-table-column></el-table></el-dialog></div></template>
